import re


def parse_duration(text):
    """Convert a nonnegative integer with an s, m or h suffix to seconds."""
    if re.fullmatch(r"[0-9]+[smh]", text) is None:
        raise ValueError(
            "duration must be a nonnegative integer followed by s, m or h "
            "with no whitespace (for example, 10m)"
        )
    return int(text[:-1]) * {"s": 1, "m": 60, "h": 3600}[text[-1]]

