from pathlib import Path
import subprocess
import sys
import unittest


CLI = Path(__file__).resolve().with_name("cli.py")


class CliTests(unittest.TestCase):
    def run_cli(self, *arguments):
        return subprocess.run(
            [sys.executable, str(CLI), *arguments],
            capture_output=True, text=True, check=False,
        )

    def test_success(self):
        for argument, expected in (("0s", "0\n"), ("12m", "720\n"), ("2h", "7200\n")):
            with self.subTest(argument=argument):
                result = self.run_cli(argument)
                self.assertEqual(result.returncode, 0)
                self.assertEqual(result.stdout, expected)
                self.assertEqual(result.stderr, "")

    def test_invalid_input(self):
        for argument in ("", "-1s", "1.5m", " 1h", "1s\n", "1d"):
            with self.subTest(argument=argument):
                self.assert_cli_error(self.run_cli(argument))

    def test_exactly_one_argument_required(self):
        for arguments in ((), ("1s", "2m")):
            with self.subTest(arguments=arguments):
                self.assert_cli_error(self.run_cli(*arguments))

    def assert_cli_error(self, result):
        self.assertEqual(result.returncode, 2)
        self.assertEqual(result.stdout, "")
        self.assertIn("error:", result.stderr)
        self.assertIn("duration", result.stderr)
        self.assertNotIn("Traceback", result.stderr)


if __name__ == "__main__":
    unittest.main()
